public void testRecoverWithDelegatedCentralizedToCentralized()
    throws Exception {
  // Node to labels mapping is not persisted when the node-label
  // configuration type is delegated-centralized, so the mirror won't
  // contain any node to labels mapping.
  mgr.stop();

  mgr = new MockNodeLabelManager();
  Configuration delegatedConf = new Configuration(conf);
  delegatedConf.set(YarnConfiguration.NODELABEL_CONFIGURATION_TYPE,
      YarnConfiguration.DELEGATED_CENTALIZED_NODELABEL_CONFIGURATION_TYPE);
  mgr.init(delegatedConf);
  mgr.start();

  mgr.addToCluserNodeLabelsWithDefaultExclusivity(toSet("p1", "p2", "p3"));
  mgr.replaceLabelsOnNode((Map) ImmutableMap.of(toNodeId("n1"), toSet("p1"),
      toNodeId("n2"), toSet("p2")));
  mgr.stop();

  // Transit the node-label configuration type back to centralized, the
  // recovery should not fail even though node to labels mapping is
  // missing from the mirror.
  mgr = new MockNodeLabelManager();
  mgr.init(conf);
  mgr.start();

  // check variables
  Assert.assertEquals(3, mgr.getClusterNodeLabelNames().size());
  Assert.assertTrue(mgr.getClusterNodeLabelNames().containsAll(
      Arrays.asList("p1", "p2", "p3")));

  mgr.stop();
}

